	cjs.MovieClip.apply(this,[props]);

	this.actionFrames = [0,1];
	// timeline functions:
	this.frame_0 = function() {
		this.stop();
		document.addEventListener("keydown",handleKeyDown);
		document.addEventListener("keyup",handleKeyUp);
		
		var root = this;
		var speed = 100;
		
		function handleKeyDown(event){
			console.log(root.background_mc.x)
			if (root.mrRobit_mc.currentFrame == 93){
				root.mrRobit_mc.gotoAndPlay("walking");
			}
			if (event.keyCode == 39 && root.background_mc.x > -2840) {
				root.mrRobit_mc.scaleX = 1;
				root.background_mc.x = root.background_mc.x - speed;
			}
		
			if (event.keyCode == 37 && root.background_mc.x < 860) {
				root.mrRobit_mc.scaleX = -1;
				root.background_mc.x = root.background_mc.x + speed;
			}
		}
		
		function handleKeyUp(event){
			root.mrRobit_mc.gotoAndPlay("standing");
		}
		
		this.background_mc.shopSign_mc.addEventListener("click",handleClickShop);
		
		function handleClickShop(event){
			root.background_mc.shopSign_mc.play();
			root.background_mc.shopSign_mc.removeEventListener("click",handleClickShop);
		}
		
		this.background_mc.clickDoor_mc.addEventListener("click",handleClickDoor);
		
		function handleClickDoor(event){
			root.background_mc.clickDoor_mc.play();
			root.background_mc.clickDoor_mc.removeEventListener("click",handleClickDoor);
			var knock_snd = createjs.Sound.play("knock");
		}
		
		this.play_btn.addEventListener("click",handleClickPlayButton);
		
		function handleClickPlayButton(event){
			root.play();
			var stick_snd = createjs.Sound.play("music");
		}
	}
	this.frame_1 = function() {
		this.stop();
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1).call(this.frame_1).wait(1));

